/**
 * Stable identifiers are opaque strings generated by the application boundary.
 * Domain types deliberately do not prescribe an ID-generation mechanism.
 */
export type CVDocumentId = string;
export type CVSectionId = string;
export type CVEntryId = string;

/**
 * ISO-8601 timestamp string. Runtime parsing/validation belongs to a later
 * domain-validation or project-import boundary.
 */
export type ISODateTimeString = string;

/**
 * A person's name is intentionally decomposed so consumers do not have to
 * parse a display string to access its parts.
 */
export interface PersonName {
  givenName?: string;
  additionalName?: string;
  familyName?: string;
  prefix?: string;
  suffix?: string;
}

/** A postal address, with each component independently optional. */
export interface PostalAddress {
  addressLine1?: string;
  addressLine2?: string;
  locality?: string;
  region?: string;
  postalCode?: string;
  country?: string;
}

/** An external profile or portfolio link associated with the person. */
export interface ProfileLink {
  label: string;
  url: string;
}

/**
 * Contact information is optional because a newly created CV may be
 * incomplete. Absence is represented by an omitted property, not null.
 */
export interface ContactDetails {
  email?: string;
  phone?: string;
  website?: string;
  address?: PostalAddress;
  profiles?: readonly ProfileLink[];
}

/** Factual identity and contact information belonging to the CV owner. */
export interface PersonalDetails {
  name?: PersonName;
  headline?: string;
  contact?: ContactDetails;
}

/**
 * Shared entry identity contract. The content type is supplied by a
 * section-specific model; unknown is used until that model is defined.
 */
export interface CVSectionEntry<TContent = unknown> {
  id: CVEntryId;
  content: TContent;
}

/**
 * Shared section contract. TKind is the discriminant used by concrete
 * section variants, while TContent describes the payload of each entry.
 */
export interface CVSection<
  TKind extends string = string,
  TContent = unknown,
> {
  id: CVSectionId;
  kind: TKind;
  title?: string;
  entries: readonly CVSectionEntry<TContent>[];
}

/** Factual CV information, kept independent of visual presentation/layout. */
export interface CVContent {
  personalDetails: PersonalDetails;
  sections: readonly CVSection[];
}

/** Descriptive document metadata, separate from factual CV content. */
export interface CVDocumentMetadata {
  title: string;
  createdAt: ISODateTimeString;
  updatedAt: ISODateTimeString;
}

/** Root in-memory CV document contract. */
export interface CVDocument {
  id: CVDocumentId;
  metadata: CVDocumentMetadata;
  content: CVContent;
}
